# -*- coding: utf-8 -*-
"""Handle pricing endpoints for MT4 (replaces OANDA)."""

import time
import json
import os
from datetime import datetime
from abc import abstractmethod
from types import GeneratorType

from .apirequest import APIRequest
from ..exceptions import StreamTerminated
from .decorators import dyndoc_insert, endpoint
from .responses.pricing import responses


class Pricing(APIRequest):
    """Pricing - class to handle pricing endpoint (MT4 version)."""

    ENDPOINT = ""
    METHOD = "GET"

    @abstractmethod
    def __init__(self, accountID):
        """Instantiate a Pricing APIRequest instance.

        Parameters
        ----------
        accountID : string (required)
            the accountID of the account (for MT4, can be any identifier).

        """
        endpoint = self.ENDPOINT.format(accountID=accountID)
        super(Pricing, self).__init__(endpoint, method=self.METHOD)


@endpoint("mt4/pricing")
class PricingInfo(Pricing):
    """
    MT4 Pricing Info (replaces OANDA PricingInfo).
    
    Get pricing information for specified instruments from MT4.
    """

    @dyndoc_insert(responses)
    def __init__(self, accountID, params=None):
        """Instantiate a PricingInfo APIRequest instance (MT4 version).

        Parameters
        ----------
        accountID : string (required)
            the accountID of the account.

        params : dict (required)
            parameters for the request:
            - instruments: list of instruments to get prices for
            
        Example
        -------

        >>> from mt4_pricing import PricingInfo
        >>> accountID = "MT4_ACCOUNT"
        >>> params = {"instruments": ["EURUSD", "GOLD"]}
        >>> pricing = PricingInfo(accountID=accountID, params=params)
        >>> prices = pricing.get_prices()
        >>> print(prices)
        
        Output:
        
        {
            "prices": [
                {"instrument": "EURUSD", "bid": 1.0950, "ask": 1.0952},
                {"instrument": "GOLD", "bid": 2392.50, "ask": 2392.80}
            ]
        }

        """
        super(PricingInfo, self).__init__(accountID)
        self.params = params or {}
        self._mt4 = None
    
    def _get_mt4(self):
        """Lazy load MT4 provider"""
        if self._mt4 is None:
            try:
                from mt4_price_provider import get_mt4_prices
                self._mt4 = get_mt4_prices()
            except ImportError:
                pass
        return self._mt4
    
    def get_prices(self):
        """
        Get real-time prices from MT4 (replaces OANDA API call)
        
        Returns:
        --------
        dict : Prices for requested instruments
        """
        mt4 = self._get_mt4()
        
        if not mt4 or not mt4.test_connection():
            return self._get_fallback_prices()
        
        instruments = self.params.get("instruments", [])
        prices = []
        
        for instrument in instruments:
            price_data = mt4.get_price(instrument)
            
            if price_data.get('success'):
                prices.append({
                    "instrument": instrument,
                    "bid": price_data.get('bid', 0),
                    "ask": price_data.get('ask', 0),
                    "mid": price_data.get('mid', 0),
                    "spread": price_data.get('spread', 0),
                    "time": datetime.now().isoformat()
                })
            else:
                prices.append({
                    "instrument": instrument,
                    "bid": 0,
                    "ask": 0,
                    "mid": 0,
                    "error": "No data"
                })
        
        return {"prices": prices}
    
    def _get_fallback_prices(self):
        """Fallback prices when MT4 is not connected"""
        instruments = self.params.get("instruments", [])
        prices = []
        
        fallback_data = {
            "EURUSD": {"bid": 1.0950, "ask": 1.0952},
            "GBPUSD": {"bid": 1.2850, "ask": 1.2853},
            "GOLD": {"bid": 2392.50, "ask": 2392.80},
            "SILVER": {"bid": 28.45, "ask": 28.48},
            "BRENT_OIL": {"bid": 89.75, "ask": 89.80},
            "S&P500": {"bid": 5200.50, "ask": 5201.00},
            "NAS100": {"bid": 18250.00, "ask": 18255.00}
        }
        
        for instrument in instruments:
            data = fallback_data.get(instrument, {"bid": 0, "ask": 0})
            prices.append({
                "instrument": instrument,
                "bid": data["bid"],
                "ask": data["ask"],
                "mid": (data["bid"] + data["ask"]) / 2,
                "source": "FALLBACK"
            })
        
        return {"prices": prices}
    
    @property
    def response(self):
        """
        Get pricing response (compatible with OANDA interface)
        """
        return self.get_prices()


class PricingStream(Pricing):
    """
    MT4 Pricing Stream (replaces OANDA PricingStream).
    
    Get realtime pricing stream from MT4 (simulated for compatibility).
    """

    STREAM = True

    @dyndoc_insert(responses)
    def __init__(self, accountID, params=None):
        """Instantiate a PricingStream APIRequest instance (MT4 version).

        Parameters
        ----------
        accountID : string (required)
            the accountID of the account.

        params : dict (required)
            parameters for the request:
            - instruments: list of instruments to stream
            - interval: update interval in seconds (default 1)

        Example
        -------

        >>> from mt4_pricing import PricingStream
        >>> accountID = "MT4_ACCOUNT"
        >>> params = {"instruments": ["EURUSD", "GOLD"], "interval": 0.5}
        >>> stream = PricingStream(accountID=accountID, params=params)
        >>> for price in stream:
        >>>     print(price)

        """
        super(PricingStream, self).__init__(accountID)
        self.params = params or {}
        self.interval = self.params.get("interval", 1.0)
        self.instruments = self.params.get("instruments", [])
        self._mt4 = None
        self._generator = None
        self._running = True
    
    def _get_mt4(self):
        """Lazy load MT4 provider"""
        if self._mt4 is None:
            try:
                from mt4_price_provider import get_mt4_prices
                self._mt4 = get_mt4_prices()
            except ImportError:
                pass
        return self._mt4
    
    def __iter__(self):
        """Return iterator for streaming prices"""
        if self._generator is None:
            self._generator = self._price_stream()
        return self
    
    def __next__(self):
        """Get next price in stream"""
        if not self._running:
            raise StopIteration
        
        if self._generator is None:
            self._generator = self._price_stream()
        
        return next(self._generator)
    
    def _price_stream(self):
        """Generate price stream (replaces OANDA stream)"""
        mt4 = self._get_mt4()
        
        if not mt4:
            # Simulated stream for testing
            import random
            while self._running:
                price_data = {}
                for instrument in self.instruments:
                    base_price = self._get_base_price(instrument)
                    variation = random.uniform(-0.001, 0.001)
                    price_data[instrument] = {
                        "instrument": instrument,
                        "bid": base_price + variation,
                        "ask": base_price + variation + 0.0002,
                        "time": datetime.now().isoformat()
                    }
                yield price_data
                time.sleep(self.interval)
            return
        
        # Real MT4 price stream
        last_prices = {}
        
        while self._running:
            price_data = {}
            
            for instrument in self.instruments:
                price_info = mt4.get_price(instrument)
                
                if price_info.get('success'):
                    current_bid = price_info.get('bid', 0)
                    current_ask = price_info.get('ask', 0)
                    
                    # Only yield if price changed
                    last_bid = last_prices.get(instrument, {}).get('bid')
                    
                    if last_bid != current_bid:
                        price_data[instrument] = {
                            "instrument": instrument,
                            "bid": current_bid,
                            "ask": current_ask,
                            "mid": price_info.get('mid', 0),
                            "spread": price_info.get('spread', 0),
                            "time": datetime.now().isoformat()
                        }
                        last_prices[instrument] = {"bid": current_bid, "ask": current_ask}
            
            if price_data:
                yield price_data
            
            time.sleep(self.interval)
    
    def _get_base_price(self, instrument):
        """Get base price for simulated stream"""
        base_prices = {
            "EURUSD": 1.0950,
            "GBPUSD": 1.2850,
            "GOLD": 2392.50,
            "SILVER": 28.45,
            "BRENT_OIL": 89.75
        }
        return base_prices.get(instrument, 1.0)
    
    def terminate(self, message=""):
        """Terminate the stream.

        Calling this method will stop the generator yielding tick records.
        A message can be passed optionally.
        """
        self._running = False
        
        if self._generator is not None:
            try:
                self._generator.close()
            except Exception:
                pass
        
        if not isinstance(self.response, GeneratorType):
            raise ValueError("request does not contain a stream response")
        
        self.response.throw(StreamTerminated(message))
    
    @property
    def response(self):
        """Get stream response for compatibility"""
        return self


# ============ Helper Functions ============

def get_mt4_pricing(instruments, accountID="MT4_ACCOUNT"):
    """
    Quick helper to get MT4 pricing (replaces OANDA pricing call)
    
    Parameters:
    -----------
    instruments : list
        List of instrument symbols
    accountID : str
        Account identifier
    
    Returns:
    --------
    dict : Pricing information
    """
    pricing = PricingInfo(accountID, params={"instruments": instruments})
    return pricing.get_prices()


def create_mt4_stream(instruments, interval=1.0, accountID="MT4_ACCOUNT"):
    """
    Create a price stream for MT4 instruments
    
    Parameters:
    -----------
    instruments : list
        List of instrument symbols
    interval : float
        Update interval in seconds
    accountID : str
        Account identifier
    
    Returns:
    --------
    PricingStream : Stream generator
    """
    params = {"instruments": instruments, "interval": interval}
    return PricingStream(accountID, params=params)
